      "en": "Indeed, I am your Lord, so remove your sandals. Indeed, you are in the blessed valley of Ṭuwā.",
      "footnotesUr": "[1] جوتیاں اتارنے کا حکم اس لئے دیا کہ اس میں تواضع کا اظہار اور شرف و تکریم کا پہلو زیادہ ہے، بعض کہتے ہیں کہ وہ ایسے گدھے کی کھال کی بنی ہوئی تھی جو غیر مدبوغ تھی۔ کیوں کہ جانور کی کھال دباغت کے بعد ہی پاک ہوتی ہے، مگر یہ قول محل نظر ہے۔ دباغت کے بغیر جوتیاں کیوں کر بن سکتی ہیں؟ یا وادی کی پاکیزگی اس کا سبب تھا، جیسا کہ قرآن کے الفاظ سے واضح ہوتا ہے۔ تاہم اس کے دو پہلو ہیں۔ یہ حکم وادی کی تعظیم کے لئے تھا یا اس لئے کہ وادی کی پاکیزگی کے اثرات ننگے پیر ہونے کی صورت میں موسیٰ (عليه السلام) کے اندر زیادہ جذب ہو سکیں۔ واللہ اعلم۔\n[2] طُوًى وادی کا نام ہے، اسے بعض نے منصرف اور بعض نے غیر منصرف کہا ہے (فتح القدیر)",
