      "arFull": "وَاَشْرِكْهُ فِیْۤ اَمْرِیْ ۟ۙ",
      "ur": "اور اسے میرا شریک کار کر دے.[1]",
      "en": "And let him share my task",
      "footnotesUr": "[1] کہتے ہیں کہ موسیٰ (عليه السلام) جب فرعون کے شاہی محل میں زیر پرورش تھے تو کھجور یا موتی کی بجائے آگ کا انگارا منہ میں ڈال لیا تھا جس سے ان کی زبان جل گئی اور اس میں لکنت پیدا ہوگئی (ابن کثیر) جب اللہ تعالٰی نے انہیں حکم دیا کہ فرعون کے پاس جا کر میرا پیغام پہنچاؤ تو حضرت موسیٰ (عليه السلام) کے دل میں دو باتیں آئیں ایک تو یہ کہ وہ بڑا جابر اور متکبر بادشاہ ہے بلکہ رب ہونے تک کا دعویدار ہے دوسرا یہ کہ موسیٰ (عليه السلام) کے ہاتھوں اس کی قوم کا ایک آدمی مارا گیا تھا اور جس کی وجہ سے موسیٰ کو اپنی جان بچانے کے لیے وہاں سے نکلنا پڑا تھا یعنی ایک فرعون کی عظمت وجباریت کا خوف اور دوسرا اپنے ہاتھوں ہونے والے واقعہ کا اندیشہ اور ان دونوں پر زائد تیسری بات زبان میں لکنت۔ حضرت موسیٰ (عليه السلام) نے دعا فرمائی کہ یا اللہ! میرا سینہ کھول دے تاکہ میں رسالت کا بوجھ اٹھا سکوں میرے کام کو آسان فرما دے یعنی جو مہم مجھے درپیش ہے اس میں میری مدد فرما اور میری زبان کی گرہ کھول دے تاکہ فرعون کے سامنے میں پوری وضاحت سے تیرا پیغام پہنچا سکوں اور اگر ضرورت پیش آئے تو اپنا دفاع بھی کر سکوں۔ اس کے ساتھ یہ دعا بھی کی کہ میرے بھائی ہارون (عليه السلام) کو (کہتے ہیں کہ یہ عمر میں موسیٰ عليه السلام سے بڑے تھے) بطور معین اور مددگار، میرا وزیر اور شریک کار بنا دے۔ وَزِيرٌ مُوَازِرٌ کے معنی میں ہے یعنی بوجھ اٹھانے والا جس طرح ایک وزیر بادشاہ کا بوجھ اٹھاتا ہے اور امور مملکت میں اسکا مشیر ہوتا ہے اسی طرح ہارون (عليه السلام) میرا مشیر اور بوجھ اٹھانے والا ساتھی ہو۔",
