      "arFull": "قَالَ اَجِئْتَنَا لِتُخْرِجَنَا مِنْ اَرْضِنَا بِسِحْرِكَ یٰمُوْسٰی ۟",
      "ur": "کہنے لگا اے موسیٰ! کیا تو اسی لئے آیا ہے کہ ہمیں اپنے جادو کے زور سے ہمارے ملک سے باہر نکال دے.[1]",
      "en": "He said, \"Have you come to us to drive us out of our land with your magic, O Moses?",
      "footnotesUr": "[1] جب فرعون کو دلائل واضحہ کے ساتھ وہ معجزات بھی دکھلائے گئے، جو عصا اور ید بیضا کی صورت میں حضرت موسیٰ (عليه السلام) کو عطا کئے گئے تھے، تو فرعون نے اسے جادو کا کرتب سمجھا اور کہنے لگا اچھا تو ہمیں اس جادو کے زور سے ہماری زمین سے نکالنا چاہتا ہے؟۔",
