      "arFull": "جَنّٰتُ عَدْنٍ تَجْرِیْ مِنْ تَحْتِهَا الْاَنْهٰرُ خٰلِدِیْنَ فِیْهَا ؕ وَذٰلِكَ جَزٰٓؤُا مَنْ تَزَكّٰی ۟۠",
      "ur": "ہمیشگی والی جنتیں جن کے نیچے نہریں لہریں لے رہی ہیں جہاں وه ہمیشہ (ہمیشہ) رہیں گے۔ یہی انعام ہے ہر اس شخص کا جو پاک ہوا.[1]",
      "en": "Gardens of perpetual residence beneath which rivers flow, wherein they abide eternally. And that is the reward of one who purifies himself.[844]",
      "footnotesUr": "[1] جہنمیوں کے مقابلے میں اہل ایمان کو جو جنت کی پر آسائش زندگی ملے گی، اس کا ذکر فرمایا اور واضح کر دیا کہ اس کے مستحق وہ لوگ ہونگے جو ایمان لانے کے بعد اس کے تقاضے پورے کریں گے۔ یعنی اعمال صالح اختیار اور اپنے نفس کو گناہوں کی آلودگی سے پاک کریں گے۔ اس لئے کہ ایمان زبان سے صرف چند کلمات ادا کر دینے کا نام نہیں ہے بلکہ عقیدہ و عمل کے مجموعے کا نام ہے۔",
