      "arFull": "قَالَ بَصُرْتُ بِمَا لَمْ یَبْصُرُوْا بِهٖ فَقَبَضْتُ قَبْضَةً مِّنْ اَثَرِ الرَّسُوْلِ فَنَبَذْتُهَا وَكَذٰلِكَ سَوَّلَتْ لِیْ نَفْسِیْ ۟",
      "ur": "اس نے جواب دیا کہ مجھے وه چیز دکھائی دی جو انہیں دکھائی نہیں دی، تو میں نے فرستادہٴ الٰہی کے نقش قدم سے ایک مٹھی بھر لی اسے اس میں ڈال دیا[1] اسی طرح میرے دل نے یہ بات میرے لئے بھلی بنا دی.",
      "en": "He said, \"I saw what they did not see, so I took a handful [of dust] from the track of the messenger[850] and threw it,[851] and thus did my soul entice me.\"",
      "footnotesUr": "[1] جمہور مفسرین نے الرَّسُولِ سے مراد جبرائیل (عليه السلام) لئے ہیں اور مطلب یہ بیان کیا ہے کہ جبرائیل (عليه السلام) کے گھوڑے کو گزرتے ہوئے سامری نے دیکھا اور اس کے قدموں کے نیچے کی مٹی اس نے سنبھال رکھ لی، جس میں کچھ کرامات کے اثرات تھے۔ اس مٹی کی مٹھی اس نے پگھلے ہوئے زیورات یا بچھڑے میں ڈالی تو اس میں سے ایک قسم کی آواز نکلنی شروع ہوگئی جو ان کے فتنے کا باعث بن گئی۔",
