      "arFull": "وَكَذٰلِكَ نَجْزِیْ مَنْ اَسْرَفَ وَلَمْ یُؤْمِنْ بِاٰیٰتِ رَبِّهٖ ؕ وَلَعَذَابُ الْاٰخِرَةِ اَشَدُّ وَاَبْقٰی ۟",
